package com.microservices.api_gateway;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;

@SpringBootApplication
@EnableDiscoveryClient
public class ApiGatewayApplication {

	public static void main(String[] args) {
		SpringApplication.run(ApiGatewayApplication.class, args);
	}

}

package com.microservices.api_gateway.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import com.common.jwt.JwtTokenProvider;

import jakarta.annotation.PostConstruct;
import java.time.Instant;
import java.util.Date;

@Configuration
public class JwtConfig {

    private static final Logger logger = LoggerFactory.getLogger(JwtConfig.class);

    @Value("${jwt.secret}")
    private String secretKeyString;

    @Value("${jwt.access-token-expire-time}")
    private long accessTokenExpirationTime;

    @Value("${jwt.refresh-token-expire-time}")
    private long refreshTokenExpirationTime;

    @PostConstruct
    public void checkSystemTime() {
        logger.info("=== 시스템 시간 확인 ===");
        logger.info("현재 시간: {}", new Date());
        logger.info("시스템 시간 밀리초: {}", System.currentTimeMillis());
        logger.info("JVM 시간: {}", Instant.now());
        logger.info("=======================");
    }

    @Bean
    public JwtTokenProvider jwtTokenProvider() {
        logger.info("API Gateway - accessTokenExpirationTime: {}", accessTokenExpirationTime);
        logger.info("API Gateway - refreshTokenExpirationTime: {}", refreshTokenExpirationTime);
        logger.info("API Gateway - secretKeyString: '{}'", secretKeyString);
        logger.info("API Gateway - secretKeyString 길이: {}", secretKeyString.length());

        return new JwtTokenProvider(secretKeyString, accessTokenExpirationTime, refreshTokenExpirationTime);
    }
}

package com.microservices.api_gateway.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpStatus;
import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity;
import org.springframework.security.config.web.server.SecurityWebFiltersOrder;
import org.springframework.security.config.web.server.ServerHttpSecurity;
import org.springframework.security.web.server.SecurityWebFilterChain;

import com.common.jwt.JwtTokenProvider;
import com.common.jwt.config.JwtFilterConfigurer;
import com.common.jwt.filter.ReactiveJwtAuthenticationFilter;
import com.microservices.api_gateway.security.redis.RedisTokenBlacklistAdapter;

@Configuration
@EnableWebFluxSecurity
public class SecurityConfig {

    private final JwtTokenProvider jwtTokenProvider;
    private final RedisTokenBlacklistAdapter tokenBlacklistService;

    public SecurityConfig(JwtTokenProvider jwtTokenProvider, RedisTokenBlacklistAdapter tokenBlacklistService) {
        this.jwtTokenProvider = jwtTokenProvider;
        this.tokenBlacklistService = tokenBlacklistService;
    }

    @Bean
    public SecurityWebFilterChain securityWebFilterChain(ServerHttpSecurity http) {

        // 공통 JWT 필터 생성
        ReactiveJwtAuthenticationFilter jwtAuthenticationFilter = 
            JwtFilterConfigurer.createReactiveFilter(jwtTokenProvider, tokenBlacklistService);

        return http.csrf(csrfCustomizer -> csrfCustomizer.disable())
            .cors(corsCustomizer -> corsCustomizer.disable()) // CORS 비활성화 (필요시 별도 설정)
            .exceptionHandling(exceptionHandlingCustomizer -> 
                exceptionHandlingCustomizer.authenticationEntryPoint((exchange, ex) -> {
                    exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
                    return exchange.getResponse().setComplete();
                }))
            .authorizeExchange(exchanges -> exchanges
                .pathMatchers("/auth/login", "/auth/register", "/auth/hello", "/auth/refresh", "/public/**").permitAll()
                .anyExchange().authenticated()
            )
            .addFilterAt(jwtAuthenticationFilter, SecurityWebFiltersOrder.AUTHENTICATION)
            .build(); 

    }
}

package com.microservices.api_gateway.security.redis;

import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.connection.RedisStandaloneConfiguration;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.connection.lettuce.LettucePoolingClientConfiguration;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;
import org.springframework.data.redis.serializer.StringRedisSerializer;

@Configuration
public class RedisConfig {

    @Value("${spring.data.redis.host}")
    private String redisHost;

    @Value("${spring.data.redis.port}")
    private int redisPort;

    // application.yml에 정의된 Lettuce pool 설정을 가져오기 위한 값들
    @Value("${spring.data.redis.lettuce.pool.max-active:8}") // 기본값 8
    private int maxActive;

    @Value("${spring.data.redis.lettuce.pool.max-idle:8}") // 기본값 8
    private int maxIdle;

    @Value("${spring.data.redis.lettuce.pool.min-idle:0}") // 기본값 0
    private int minIdle;

    @Value("${spring.data.redis.lettuce.pool.max-wait:-1}") // 기본값 -1 (무한 대기)
    private long maxWaitMillis;

    @Bean
    public LettuceConnectionFactory redisConnectionFactory() {
        RedisStandaloneConfiguration redisStandaloneConfiguration = new RedisStandaloneConfiguration(redisHost,
                redisPort);
        // 비밀번호가 있다면 설정:
        // redisStandaloneConfiguration.setPassword(RedisPassword.of("your-password"));

        // Lettuce 풀 설정
        GenericObjectPoolConfig<Object> poolConfig = new GenericObjectPoolConfig<>();
        poolConfig.setMaxTotal(maxActive);
        poolConfig.setMaxIdle(maxIdle);
        poolConfig.setMinIdle(minIdle);
        poolConfig.setMaxWait(java.time.Duration.ofMillis(maxWaitMillis));
        // poolConfig.setTestOnBorrow(true); // 풀에서 커넥션을 가져올 때 유효성 검사 (성능에 영향 줄 수 있음)
        // poolConfig.setTestOnReturn(true); // 풀에 커넥션을 반환할 때 유효성 검사 (성능에 영향 줄 수 있음)

        LettucePoolingClientConfiguration clientConfig = LettucePoolingClientConfiguration.builder()
                .poolConfig(poolConfig)
                // .commandTimeout(Duration.ofMillis(timeout)) // application.yml의
                // spring.data.redis.timeout 사용 가능
                .build();

        return new LettuceConnectionFactory(redisStandaloneConfiguration, clientConfig);
    }

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        // application.yml의 값으로 생성된 connectionFactory 사용
        template.setConnectionFactory(connectionFactory);

        // 직렬화 설정
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        template.setHashKeySerializer(new StringRedisSerializer());
        template.setHashValueSerializer(new GenericJackson2JsonRedisSerializer());

        template.afterPropertiesSet();
        return template;
    }

}

package com.microservices.api_gateway.security.redis;

import java.time.Duration;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.QueryTimeoutException;
import org.springframework.data.redis.RedisConnectionFailureException; // Redis 연결 실패 예외
import org.springframework.data.redis.core.RedisTemplate; // Redis 템플릿
import org.springframework.stereotype.Service; // 서비스 어노테이션

import reactor.core.publisher.Mono; // 리액터 Mono

@Service
public class RedisService {

    private static final Logger logger = LoggerFactory.getLogger(RedisService.class); // 로거 생성
    private final RedisTemplate<String, Object> redisTemplate;
    private static final String ACCESS_TOKEN_BLACKLIST_KEY_PREFIX = "blacklist:";

    public RedisService(RedisTemplate<String, Object> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    public Mono<Boolean> isBlacklisted(String token) {
        return Mono.fromCallable(() -> {
            try {
                return redisTemplate.hasKey(ACCESS_TOKEN_BLACKLIST_KEY_PREFIX + token); // Redis에서 키 존재 여부 확인
            } catch (RedisConnectionFailureException | QueryTimeoutException e) {
                logger.error("Redis connection error while checking blacklist for token: {}", token, e);
                return false; // Redis 연결 실패 시 false 반환 (서비스 지속성을 위해)
                              // 필요에 따라 사용자 정의 예외를 던질 수도 있음.
                              // throw new CustomRedisUnavailableException("Redis is unavailable", e);
            }
        });
    }

    public Mono<Void> blacklistToken(String token, long expirationTime) {
        return Mono.fromRunnable(() -> {
            try {
                // 키를 일관성 있게 설정
                redisTemplate.opsForValue().set(ACCESS_TOKEN_BLACKLIST_KEY_PREFIX + token, "blacklisted", Duration.ofMillis(expirationTime));
            } catch (RedisConnectionFailureException | QueryTimeoutException e) {
                logger.error("Redis connection error while blacklisting token: {}", token, e);
                throw e;
            } catch (Exception e) {
                logger.error("Redis error while blacklisting token: {}", token, e);
                throw e;
            }
        });
    }

}

package com.microservices.api_gateway.security.redis;

import com.common.jwt.authentication.TokenBlacklistService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;

/**
 * Redis 기반 토큰 블랙리스트 서비스 어댑터
 * 기존 RedisService를 공통 TokenBlacklistService 인터페이스에 맞게 래핑
 */
@Component
public class RedisTokenBlacklistAdapter implements TokenBlacklistService {
    
    private static final Logger logger = LoggerFactory.getLogger(RedisTokenBlacklistAdapter.class);
    
    private final RedisService redisService;
    
    public RedisTokenBlacklistAdapter(RedisService redisService) {
        this.redisService = redisService;
    }
    
    @Override
    public void blacklistToken(String token, long expireTimeMs) {
        try {
            redisService.blacklistToken(token, expireTimeMs).block();
        } catch (Exception e) {
            logger.error("Redis 토큰 블랙리스트 추가 실패: {}", e.getMessage(), e);
        }
    }
    
    @Override
    public boolean isBlacklisted(String token) {
        try {
            return Boolean.TRUE.equals(redisService.isBlacklisted(token).block());
        } catch (Exception e) {
            logger.error("Redis 블랙리스트 확인 실패: {}", e.getMessage(), e);
            return false; // 오류 시 허용적으로 처리
        }
    }
    
    @Override
    public Mono<Void> blacklistTokenAsync(String token, long expireTimeMs) {
        return redisService.blacklistToken(token, expireTimeMs)
            .onErrorResume(error -> {
                logger.error("Redis 비동기 토큰 블랙리스트 추가 실패: {}", error.getMessage(), error);
                return Mono.empty();
            });
    }
    
    @Override
    public Mono<Boolean> isBlacklistedAsync(String token) {
        return redisService.isBlacklisted(token)
            .onErrorReturn(false); // 오류 시 허용적으로 처리
    }
}

import static org.assertj.core.api.Assertions.assertThat;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.RedisTemplate;

import com.microservices.api_gateway.ApiGatewayApplication;

@SpringBootTest(classes = ApiGatewayApplication.class) // RedisConfig 클래스를 사용하여 테스트 컨텍스트를 로드합니다.
public class RedisConnectionTest {

    @Autowired
    private RedisTemplate redisTemplate;

    @Test
    void redisConnectionTest() {
        // Redis에 연결 테스트
        String key = "testKey";
        String value = "testValue";

        // Redis에 데이터 저장
        redisTemplate.opsForValue().set(key, value);

        // Redis에서 데이터 조회
        String retrievedValue = (String) redisTemplate.opsForValue().get(key);

        // 결과 출력
        assertThat(retrievedValue).isEqualTo(value);
    }
    
}

