    @Test
    void testLoginSuccess() throws Exception {
        // Given
        LoginRequest request = new LoginRequest("testuser", "password");
        
        // LoginResponse.builder()를 사용하여 올바른 응답 생성
        LoginResponse mockResponse = LoginResponse.builder()
            .accessToken("mock-access-token")
            .refreshToken("mock-refresh-token")
            .username("testuser")
            .userId(1L)
            .success(true)
            .message("Login successful")
            .build();
        
        // MenuDto.builder()를 사용하여 올바른 메뉴 생성
        MenuDto menuDto = MenuDto.builder()
            .menuCode("TEST001")
            .menuAlias("Test Menu")
            .path("/test")
            .isActive(true)
            .build();
        
        when(authService.authenticate(any(LoginRequest.class), anyString()))
            .thenReturn(mockResponse);
        when(menuService.getMenuListByUserInfo(any(Long.class)))
            .thenReturn(Arrays.asList(menuDto));

        // When & Then
        mockMvc.perform(post("/auth/login")
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(request)))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.success").value(true))
            .andExpect(jsonPath("$.message").value("Login successful"))
            .andExpect(jsonPath("$.accessToken").value("mock-access-token"))
            .andExpect(jsonPath("$.username").value("testuser"));
