        assertNotNull(response);
        assertTrue(response.isSuccess());
        assertEquals("mock-access-token", response.getAccessToken());
        assertEquals("mock-refresh-token", response.getRefreshToken());
        assertEquals("Bearer", response.getTokenType());
        assertEquals(3600, response.getExpiresIn());
        assertEquals("testuser", response.getUsername());
        assertEquals(1L, response.getUserId());
        assertEquals("Test User", response.getName());
        assertEquals("Test Tenant", response.getTenantName());
        assertEquals("test@example.com", response.getEmail());
        assertEquals("1", response.getTenantId());
        assertEquals(2, response.getRoles().size());
        assertTrue(response.getRoles().contains("USER"));
        assertTrue(response.getRoles().contains("ADMIN"));
    }
}

package com.microservices.auth_service.service;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import com.common.exceptions.TooManyAttemptsException;

@SpringBootTest
public class RateLimitServiceTest {

    private RateLimitService rateLimitService;

    @BeforeEach
    void setUp() {
        rateLimitService = new RateLimitService();
    }

    @Test
    void testFirstLoginAttempt() {
        String testIp = "192.168.1.1";
        
        // First login attempt should succeed
        assertDoesNotThrow(() -> rateLimitService.checkLoginAttempts(testIp));
        assertEquals(1, rateLimitService.getCurrentAttempts(testIp));
    }

    @Test
    void testMultipleLoginAttempts() {
        String testIp = "192.168.1.2";
        
        // 5 attempts should succeed
        for (int i = 0; i < 5; i++) {
            assertDoesNotThrow(() -> rateLimitService.checkLoginAttempts(testIp));
        }
        
        assertEquals(5, rateLimitService.getCurrentAttempts(testIp));
        
        // 6th attempt should be blocked
        assertThrows(TooManyAttemptsException.class, () -> 
            rateLimitService.checkLoginAttempts(testIp));
    }

    @Test
    void testResetLoginAttempts() {
        String testIp = "192.168.1.3";
        
        // Two attempts
        rateLimitService.checkLoginAttempts(testIp);
        rateLimitService.checkLoginAttempts(testIp);
        assertEquals(2, rateLimitService.getCurrentAttempts(testIp));
        
        // Reset
        rateLimitService.resetLoginAttempts(testIp);
        assertEquals(0, rateLimitService.getCurrentAttempts(testIp));
    }

    @Test
    void testBlockedIpStatus() {
        String testIp = "192.168.1.4";
        
        // Exceed maximum attempt count
        for (int i = 0; i < 6; i++) {
            try {
                rateLimitService.checkLoginAttempts(testIp);
            } catch (TooManyAttemptsException e) {
                // Expected exception
            }
        }
        
        // Check remaining time
        long remainingTime = rateLimitService.getRemainingBlockTime(testIp);
        assertTrue(remainingTime > 0, "IP should be blocked");
    }

    @Test
    void testDifferentIps() {
        String ip1 = "192.168.1.5";
        String ip2 = "192.168.1.6";
        
        // IP1 has 3 attempts
        for (int i = 0; i < 3; i++) {
            rateLimitService.checkLoginAttempts(ip1);
        }
        
        // IP2 has 2 attempts
        for (int i = 0; i < 2; i++) {
            rateLimitService.checkLoginAttempts(ip2);
        }
        
        assertEquals(3, rateLimitService.getCurrentAttempts(ip1));
        assertEquals(2, rateLimitService.getCurrentAttempts(ip2));
    }
}

package com.microservices.auth_service.service;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;
import org.mockito.junit.jupiter.MockitoExtension;

import com.microservices.auth_service.domain.entity.Tenant;
import com.microservices.auth_service.dto.TenantDto;
import com.microservices.auth_service.repository.TenantRepository;

@ExtendWith(MockitoExtension.class)
public class TenantServiceTest {

    @Mock
    private TenantRepository tenantRepository;

    @InjectMocks
    private TenantService tenantService;

    private List<Tenant> mockTenants;

    @BeforeEach
    void setUp() {
        mockTenants = new ArrayList<>();
        for (int i = 1; i <= 5; i++) {
            Tenant mockTenant = Tenant.builder()
                    .id((long) i)
                    .name("test_tenant_" + i)
                    .status(i % 2 == 0) // 짝수는 true, 홀수는 false
                    .build();
            mockTenants.add(mockTenant);
        }
    }

    @Test
    void testGetTenantList_성공() {
        // Given
        when(tenantRepository.findAll()).thenReturn(mockTenants);

        // When
        List<TenantDto> result = tenantService.getTenantList();

        // Then
        assertNotNull(result);
        assertEquals(5, result.size());
        
        // 첫 번째 테넌트 검증
        TenantDto firstTenant = result.get(0);
        assertEquals(1L, firstTenant.getId());
        assertEquals("test_tenant_1", firstTenant.getName());
        assertFalse(firstTenant.isStatus());
        
        // 두 번째 테넌트 검증
        TenantDto secondTenant = result.get(1);
        assertEquals(2L, secondTenant.getId());
        assertEquals("test_tenant_2", secondTenant.getName());
        assertTrue(secondTenant.isStatus());
        
        // Repository 메서드가 한 번 호출되었는지 검증
        verify(tenantRepository, times(1)).findAll();
    }

    @Test
    void testGetTenantList_빈리스트() {
        // Given
        when(tenantRepository.findAll()).thenReturn(new ArrayList<>());

        // When
        List<TenantDto> result = tenantService.getTenantList();

        // Then
        assertNotNull(result);
        assertTrue(result.isEmpty());
        verify(tenantRepository, times(1)).findAll();
    }

    @Test
    void testGetTenantList_단일테넌트() {
        // Given
        List<Tenant> singleTenant = List.of(
            Tenant.builder()
                .id(1L)
                .name("single_tenant")
                .status(true)
                .build()
        );
        when(tenantRepository.findAll()).thenReturn(singleTenant);

        // When
        List<TenantDto> result = tenantService.getTenantList();

        // Then
        assertNotNull(result);
        assertEquals(1, result.size());
        
        TenantDto tenantDto = result.get(0);
        assertEquals(1L, tenantDto.getId());
        assertEquals("single_tenant", tenantDto.getName());
        assertTrue(tenantDto.isStatus());
        
        verify(tenantRepository, times(1)).findAll();
    }

    @Test
    void testGetTenantList_Repository호출확인() {
        // Given
        when(tenantRepository.findAll()).thenReturn(mockTenants);

        // When
        tenantService.getTenantList();

        // Then
        verify(tenantRepository).findAll();
        verifyNoMoreInteractions(tenantRepository);
    }
}

